@prefix she:  <https://soilwise-he.github.io/soil-health#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

she:ParametersForSoilMonitoring a skos:Concept ;
    skos:prefLabel "parameters for soil monitoring" ;
    skos:narrower she:SoilErosion,
                  she:SoilCompaction .

she:SoilErosion a skos:Concept ;
    skos:prefLabel "soil erosion" ;
    skos:narrower she:Modelling,
                  she:MappingVisibleSoilErosionFeatures,
                  she:DetailsOnLandUse,
                  she:MonitoringSoilErosion .

she:Modelling a skos:Concept ;
    skos:prefLabel "modelling" ;
    she:usesDataOn she:LandCoverLandUse,
                   she:GeomorphologicalData,
                   she:NationalSoilData,
                   she:Rainfall .

she:LandCoverLandUse a skos:Concept ;
    skos:prefLabel "land cover/land use" .

she:GeomorphologicalData a skos:Concept ;
    skos:prefLabel "geomorphological data" .

she:NationalSoilData a skos:Concept ;
    skos:prefLabel "national soil data" .

she:Rainfall a skos:Concept ;
    skos:prefLabel "rainfall" .

she:MappingVisibleSoilErosionFeatures a skos:Concept ;
    skos:prefLabel "mapping visible soil erosion features" .

she:DetailsOnLandUse a skos:Concept ;
    skos:prefLabel "details on land use" ;
    she:includes she:GroundCover .

she:GroundCover a skos:Concept ;
    skos:prefLabel "ground cover" .

she:MonitoringSoilErosion a skos:Concept ;
    skos:prefLabel "monitoring (measurements) of soil erosion" ;
    she:measures she:SedimentLoads ;
    skos:narrower she:PlotScale,
                  she:CatchmentScale,
                  she:SedimentDepositionInPondsLakesOrReservoirs .

she:SedimentLoads a skos:Concept ;
    skos:prefLabel "sediment loads" .

she:PlotScale a skos:Concept ;
    skos:prefLabel "plot scale" .

she:CatchmentScale a skos:Concept ;
    skos:prefLabel "catchment scale" .

she:SedimentDepositionInPondsLakesOrReservoirs a skos:Concept ;
    skos:prefLabel "sediment deposition in ponds, lakes or reservoirs" .

she:SoilCompaction a skos:Concept ;
    skos:prefLabel "soil compaction" ;
    skos:narrower she:PrecompressionStress,
                  she:SoilRigidityRatio,
                  she:PenetrationResistance,
                  she:MorphologicalFeatures,
                  she:SoilOrganicMatter,
                  she:SaturatedHydraulicConductivity,
                  she:AirCapacity,
                  she:PlantAvailableWaterCapacity,
                  she:SoilTexture,
                  she:CoarseFragments,
                  she:CaCO3,
                  she:Rooting,
                  she:BasicSoilParametersForPTFs,
                  she:Tensiometer,
                  she:Sensors,
                  she:StressDependentMeasurements,
                  she:HigherIntensityMeasurement .

she:PrecompressionStress a skos:Concept ;
    skos:prefLabel "precompression stress" ;
    she:uses she:PedotransferFunction .

she:SoilRigidityRatio a skos:Concept ;
    skos:prefLabel "soil rigidity ratio" ;
    she:uses she:PedotransferFunction .

she:PenetrationResistance a skos:Concept ;
    skos:prefLabel "penetration resistance" ;
    she:uses she:PedotransferFunction .

she:MorphologicalFeatures a skos:Concept ;
    skos:prefLabel "morphological features" .

she:SoilOrganicMatter a skos:Concept ;
    skos:prefLabel "soil organic matter" ;
    she:measurementMethod she:Measured .

she:Measured a skos:Concept ;
    skos:prefLabel "measured" .

she:SaturatedHydraulicConductivity a skos:Concept ;
    skos:prefLabel "saturated hydraulic conductivity" ;
    she:uses she:PedotransferFunction .

she:AirCapacity a skos:Concept ;
    skos:prefLabel "air capacity" ;
    she:uses she:PedotransferFunction .

she:PlantAvailableWaterCapacity a skos:Concept ;
    skos:prefLabel "plant available water capacity" ;
    she:uses she:PedotransferFunction .

she:SoilTexture a skos:Concept ;
    skos:prefLabel "soil texture" ;
    she:estimationMethod she:Estimated .

she:CoarseFragments a skos:Concept ;
    skos:prefLabel "coarse fragments" ;
    she:estimationMethod she:Estimated .

she:CaCO3 a skos:Concept ;
    skos:prefLabel "caco3" ;
    she:estimationMethod she:Estimated .

she:Estimated a skos:Concept ;
    skos:prefLabel "estimated" .

she:Rooting a skos:Concept ;
    skos:prefLabel "rooting" ;
    she:estimationMethod she:Estimated .

she:PedotransferFunction a skos:Concept ;
    skos:prefLabel "pedotransfer function" .

she:BasicSoilParametersForPTFs a skos:Concept ;
    skos:prefLabel "all basic soil parameters for ptfs" ;
    she:measurementMethod she:Measured .

she:Tensiometer a skos:Concept ;
    skos:prefLabel "tensiometer" ;
    she:usedAt she:RepresentativeSubplots .

she:Sensors a skos:Concept ;
    skos:prefLabel "sensors" ;
    she:usedAt she:RepresentativeSubplots .

she:RepresentativeSubplots a skos:Concept ;
    skos:prefLabel "representative subplots" .

she:StressDependentMeasurements a skos:Concept ;
    skos:prefLabel "stress-dependent measurements" .

she:HigherIntensityMeasurement a skos:Concept ;
    skos:prefLabel "higher intensity measurement" ;
    she:basedOn she:LevelII ;
    she:hasCharacteristic she:GreatSamplingDepth,
                          she:MoreSubsamples .

she:LevelII a skos:Concept ;
    skos:prefLabel "level ii" .

she:GreatSamplingDepth a skos:Concept ;
    skos:prefLabel "great sampling depth" .

she:MoreSubsamples a skos:Concept ;
    skos:prefLabel "more subsamples" .

she:GreenhouseGas a skos:Concept ;
    skos:prefLabel "greenhouse gas" .

@prefix she:  <https://soilwise-he.github.io/soil-health#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

she:MeanSOCTargetValuesMatrix a skos:Concept ;
    skos:prefLabel "matrix of mean soc target values (% soil mass) for mineral cropland soils based on extensive national soil data sets" ;
    she:hasDimension she:SoilTextureClass,
                     she:ManagementIntensityFertiliser,
                     she:ClimaticWaterBalanceDuringSummer ;
    she:compiledFrom she:WessolekEtAl2008 .

she:SoilTextureClass a skos:Concept ;
    skos:prefLabel "soil texture class" ;
    skos:narrower she:Sand,
                  she:Silt,
                  she:LoamAndClay .

she:ManagementIntensityFertiliser a skos:Concept ;
    skos:prefLabel "management intensity (fertiliser)" ;
    skos:narrower she:MaxBoth,
                  she:OrganicAndMineral,
                  she:Organic,
                  she:Mineral,
                  she:Null .

she:ClimaticWaterBalanceDuringSummer a skos:Concept ;
    skos:prefLabel "climatic water balance (mm) during summer" ;
    skos:definition "negative water balance: potential evapotranspiration more than precipitation during summer. positive values indicate climate- induced surplus in the water budget from april to september." ;
    skos:narrower she:LessThanMinus100,
                  she:Minus100To0,
                  she:MoreThan0 .

she:Sand a skos:Concept ;
    skos:prefLabel "sand" .

she:Silt a skos:Concept ;
    skos:prefLabel "silt" .

she:LoamAndClay a skos:Concept ;
    skos:prefLabel "loam and clay" .

she:MaxBoth a skos:Concept ;
    skos:prefLabel "max. both" ;
    skos:definition "maximal application of organic and mineral fertiliser." .

she:OrganicAndMineral a skos:Concept ;
    skos:prefLabel "organic and mineral" .

she:Organic a skos:Concept ;
    skos:prefLabel "organic" .

she:Mineral a skos:Concept ;
    skos:prefLabel "mineral" .

she:Null a skos:Concept ;
    skos:prefLabel "null" ;
    skos:definition "null = no fertiliser applied" .

she:LessThanMinus100 a skos:Concept ;
    skos:prefLabel "less than -100" .

she:Minus100To0 a skos:Concept ;
    skos:prefLabel "-100 to 0" .

she:MoreThan0 a skos:Concept ;
    skos:prefLabel "more than 0" .

she:WessolekEtAl2008 a skos:Concept ;
    skos:prefLabel "wessolek et al. (2008)" ;
    skos:definition "data are valid for germany and neighbouring countries for different soil textures, climatic conditions and fertilisation regimes." .

she:SOCTargetValue a skos:Concept ;
    skos:prefLabel "soc target value (% soil mass)" .

she:SOCTargetValue_Sand_MaxBoth_LessThanMinus100 a she:SOCTargetValue ;
    she:hasValue "1.01" ;
    she:hasSoilTextureClass she:Sand ;
    she:hasManagementIntensity she:MaxBoth ;
    she:hasClimaticWaterBalance she:LessThanMinus100 .

she:SOCTargetValue_Sand_MaxBoth_Minus100To0 a she:SOCTargetValue ;
    she:hasValue "1.51" ;
    she:hasSoilTextureClass she:Sand ;
    she:hasManagementIntensity she:MaxBoth ;
    she:hasClimaticWaterBalance she:Minus100To0 .

she:SOCTargetValue_Sand_MaxBoth_MoreThan0 a she:SOCTargetValue ;
    she:hasValue "2.01" ;
    she:hasSoilTextureClass she:Sand ;
    she:hasManagementIntensity she:MaxBoth ;
    she:hasClimaticWaterBalance she:MoreThan0 .

she:SOCTargetValue_Sand_OrganicAndMineral_LessThanMinus100 a she:SOCTargetValue ;
    she:hasValue "0.95" ;
    she:hasSoilTextureClass she:Sand ;
    she:hasManagementIntensity she:OrganicAndMineral ;
    she:hasClimaticWaterBalance she:LessThanMinus100 .

she:SOCTargetValue_Sand_OrganicAndMineral_Minus100To0 a she:SOCTargetValu

@prefix she:  <https://soilwise-he.github.io/soil-health#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

she:SoilErosionIndicatorsToSupportAgriEnvironmentalPoliciesAtEuropeanAndGlobalLevels a skos:Concept ;
    skos:prefLabel "soil erosion indicators to support agri-environmental policies at european and global levels" ;
    skos:narrower she:AgriEnvironmentalPolicy,
                  she:Indicator .

she:AgriEnvironmentalPolicy a skos:Concept ;
    skos:prefLabel "agri-environmental policy" ;
    skos:narrower she:EUCommonAgriculturalPolicyCAP20142020,
                  she:EUResourceEfficiencyScoreboard,
                  she:EUSustainableDevelopmentGoalsIndicatorSet,
                  she:EUAgriEnvironmentalIndicatorsAEIs .

she:Indicator a skos:Concept ;
    skos:prefLabel "indicator" ;
    skos:narrower she:CAPContextIndicator42SoilErosion,
                  she:EstimatedSoilErosionByWaterAreaAffectedBySevereErosionRate,
                  she:AEI21SoilErosionMeanEstimatedRateOfSoilLossByWaterErosion .

she:EUCommonAgriculturalPolicyCAP20142020 a skos:Concept ;
    skos:prefLabel "eu: common agricultural policy (cap 2014-2020)" ;
    she:usesIndicator she:CAPContextIndicator42SoilErosion .

she:CAPContextIndicator42SoilErosion a skos:Concept ;
    skos:prefLabel "cap context indicator 42: soil erosion" ;
    skos:narrower she:EstimatedRateOfSoilLossByWaterErosion,
                  she:EstimatedAgriculturalAreaAffectedByCertainRateOfSoilErosionByWater .

she:EstimatedRateOfSoilLossByWaterErosion a skos:Concept ;
    skos:prefLabel "sub-indicator: estimated rate of soil loss by water erosion (t/ha/year)" .

she:EstimatedAgriculturalAreaAffectedByCertainRateOfSoilErosionByWater a skos:Concept ;
    skos:prefLabel "estimated agricultural area affected by a certain rate of soil erosion by water (ha)" .

she:EUResourceEfficiencyScoreboard a skos:Concept ;
    skos:prefLabel "eu: resource efficiency scoreboard" ;
    she:usesIndicator she:EstimatedSoilErosionByWaterAreaAffectedBySevereErosionRate .

she:EUSustainableDevelopmentGoalsIndicatorSet a skos:Concept ;
    skos:prefLabel "eu: sustainable development goals indicator set" ;
    she:usesIndicator she:EstimatedSoilErosionByWaterAreaAffectedBySevereErosionRate .

she:EstimatedSoilErosionByWaterAreaAffectedBySevereErosionRate a skos:Concept ;
    skos:prefLabel "estimated soil erosion by water: area affected by severe erosion rate (>10t/ha/year)" .

she:EUAgriEnvironmentalIndicatorsAEIs a skos:Concept ;
    skos:prefLabel "eu: agri-environmental indicators (aeis)" ;
    she:usesIndicator she:AEI21SoilErosionMeanEstimatedRateOfSoilLossByWaterErosion .

she:AEI21SoilErosionMeanEstimatedRateOfSoilLossByWaterErosion a skos:Concept ;
    skos:prefLabel "aei 21: soil erosion: mean estimated rate of soil loss by water erosion (t/ha/year) at various administrative levels (member state, nuts1, nuts2, nuts3)" ;
    she:measuredAtLevel she:MemberState,
                        she:NUTS1,
                        she:NUTS2,
                        she:NUTS3 .

she:NUTS a skos:Concept ;
    skos:prefLabel "nuts" ;
    skos:definition "nomenclature of territorial units for statistics" ;
    skos:narrower she:NUTS1,
                  she:NUTS2,
                  she:NUTS3 .

she:MemberState a skos:Concept ;
    skos:prefLabel "member state" .

she:NUTS1 a skos:Concept ;
    skos:prefLabel "nuts1" .

she:NUTS2 a skos:Concept ;
    skos:prefLabel "nuts2" .

she:NUTS3 a skos:Concept ;
    skos:prefLabel "nuts3" .

@prefix she:  <https://soilwise-he.github.io/soil-health#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

she:OptimalPHValuesForCrops a skos:Concept ;
    skos:prefLabel "example of optimal ph values for different crops as given in the literature" ;
    skos:narrower she:Crop,
                  she:OptimumPH .

she:Crop a skos:Concept ;
    skos:prefLabel "crop" ;
    skos:broader she:OptimalPHValuesForCrops ;
    skos:narrower she:BeetBeansPeasAndOilseeds,
                  she:CerealsAndMaize,
                  she:Grassland,
                  she:GrasslandHighMolybdenum,
                  she:Potatoes .

she:OptimumPH a skos:Concept ;
    skos:prefLabel "optimum ph" ;
    skos:broader she:OptimalPHValuesForCrops ;
    skos:narrower she:PH7_0,
                  she:PH6_5,
                  she:PH6_3,
                  she:PHLessThan6_2,
                  she:PH6_0 .

she:BeetBeansPeasAndOilseeds a skos:Concept ;
    skos:prefLabel "beet, beans, peas and oilseeds" ;
    skos:broader she:Crop ;
    she:hasOptimumPH she:PH7_0 .

she:CerealsAndMaize a skos:Concept ;
    skos:prefLabel "cereals and maize" ;
    skos:broader she:Crop ;
    she:hasOptimumPH she:PH6_5 .

she:Grassland a skos:Concept ;
    skos:prefLabel "grassland" ;
    skos:broader she:Crop ;
    she:hasOptimumPH she:PH6_3 .

she:GrasslandHighMolybdenum a skos:Concept ;
    skos:prefLabel "grassland (high molybdenum)" ;
    skos:broader she:Crop ;
    she:hasOptimumPH she:PHLessThan6_2 .

she:Potatoes a skos:Concept ;
    skos:prefLabel "potatoes" ;
    skos:broader she:Crop ;
    she:hasOptimumPH she:PH6_0 .

she:PH7_0 a skos:Concept ;
    skos:prefLabel "7.0" ;
    skos:broader she:OptimumPH .

she:PH6_5 a skos:Concept ;
    skos:prefLabel "6.5" ;
    skos:broader she:OptimumPH .

she:PH6_3 a skos:Concept ;
    skos:prefLabel "6.3" ;
    skos:broader she:OptimumPH .

she:PHLessThan6_2 a skos:Concept ;
    skos:prefLabel "<6.2" ;
    skos:broader she:OptimumPH .

she:PH6_0 a skos:Concept ;
    skos:prefLabel "6.0" ;
    skos:broader she:OptimumPH .

@prefix she:  <https://soilwise-he.github.io/soil-health#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

she:CurrentTargetsAndBaselinesForSoilSealingLandTake a skos:Concept ;
    skos:prefLabel "current targets and baselines for soil sealing/land take in selected european countries" .

she:AchieveNoNetLandTakeBy2050 a skos:Concept ;
    skos:prefLabel "achieve no net land take by 2050" ;
    skos:broader she:CurrentTargetsAndBaselinesForSoilSealingLandTake ;
    she:hasIndicator she:LandTakeKm2Per3YearPeriod ;
    she:hasSource she:EU,
                  she:RoadmapToAResourceEfficientEurope .

she:DecreaseLandTakeGradually a skos:Concept ;
    skos:prefLabel "to decrease land take gradually: 2016: land take 6ha/day (baseline) 2025 interim target 3ha/day 2040 final target 0ha/day ('land take neutral')" ;
    skos:broader she:CurrentTargetsAndBaselinesForSoilSealingLandTake ;
    she:hasIndicator she:AverageAnnualLandTakeMeasuredInHectaresPerDay ;
    she:hasSource she:Flanders,
                  she:StrategicVisionOfSpatialPolicyPlanOfFlanders .

she:ReduceAnnualLandTakeTo2_5HaDayBy2030 a skos:Concept ;
    skos:prefLabel "to reduce annual land take to a rate of 2.5ha/day by 2030 and to compensate unavoidable soil sealing" ;
    skos:broader she:CurrentTargetsAndBaselinesForSoilSealingLandTake ;
    she:hasIndicator she:AverageAnnualLandTakeMeasuredInHectaresPerDay ;
    she:hasSource she:AustrianGovernmentProgramme2020_2024 .

she:ReduceLandTakeForSettlementsAndTrafficRoutes a skos:Concept ;
    skos:prefLabel "to reduce land take for settlements and traffic routes to less than 30ha/day by 2030 (at present 52ha/day as a 4-year average from 2016 to 2019)" ;
    skos:broader she:CurrentTargetsAndBaselinesForSoilSealingLandTake ;
    she:hasIndicator she:AverageAnnualLandTakeMeasuredInHectaresPerDay ;
    she:hasSource she:GermanSustainabilityStrategy2016 .

she:ReduceLandConsumptionFrom1_3HaDayTo0HaDayBy2050 a skos:Concept ;
    skos:prefLabel "to reduce land consumption from 1.3ha/day (average 2000-2006) to 1ha/day by 2020 and 0ha/day by 2050" ;
    skos:broader she:CurrentTargetsAndBaselinesForSoilSealingLandTake ;
    she:hasIndicator she:AverageAnnualLandTakeMeasuredInHectaresPerDay ;
    she:hasSource she:Luxembourg .

she:HalveLandTakeAtExpenseOfAgriculturalLand a skos:Concept ;
    skos:prefLabel "to halve land take at the expense of agricultural land until 2020 and reduce urban sprawl" ;
    skos:broader she:CurrentTargetsAndBaselinesForSoilSealingLandTake ;
    she:hasIndicator she:AverageAnnualLandTakeMeasuredInThousandHectaresPerYearInMetropolitanAreas ;
    she:hasSource she:France .

she:StopNetLandSoilTakeBy2050 a skos:Concept ;
    skos:prefLabel "to stop net land (soil) take ('use') by 2050" ;
    skos:broader she:CurrentTargetsAndBaselinesForSoilSealingLandTake ;
    she:hasIndicator she:NotYetDefined ;
    she:hasSource she:Switzerland .

she:LandTakeKm2Per3YearPeriod a skos:Concept ;
    skos:prefLabel "land take (km²) per 3-year period" .

she:AverageAnnualLandTakeMeasuredInHectaresPerDay a skos:Concept ;
    skos:prefLabel "average annual land take measured in hectares per day" .

she:AverageAnnualLandTakeMeasuredInThousandHectaresPerYearInMetropolitanAreas a skos:Concept ;
    skos:prefLabel "average annual land take measured in thousand hectares per year in metropolitan areas" .

she:NotYetDefined a skos:Concept ;
    skos:prefLabel "not yet defined" .

she:EU a skos:Concept ;
    skos:prefLabel "eu" ;
    skos:narrower she:RoadmapToAResourceEfficientEurope .

she:RoadmapToAResourceEfficientEurope a skos:Concept ;
    skos:prefLabel "roadmap to a resource efficient europe" ;
    skos:definition "ec (2011, p. 15, milestone 4.6)." .

she:Flanders a skos:Concept ;
    skos:prefLabel "flanders" ;
    skos:narrower she:StrategicVisionOfSpatialPolicyPlanOfFlanders .

she:StrategicVisionOfSpatialPolicyPlanOfFlanders a skos:Concept ;
    skos:prefLabel "strategic vision of the spatial policy plan of flanders" ;
    skos:definition "strategic vision of the spatial policy plan of flanders (https://www.vlaanderen.be/publicaties/beleidsplan-ruimte-vlaanderen-strategische-visie-geillustreerde-versie), p. 36." .

she:AustrianGovernmentProgramme2020_2024 a skos:Concept ;
    skos:prefLabel "austrian government programme 2020-2024" ;
    skos:definition "austrian government programme 2020-2024 (https://www.bundeskanzleramt.gv.at/bundeskanzleramt/die-bundesregierung/regierungsdokumente.html), p. 104." .

she:GermanSustainabilityStrategy2016 a skos:Concept ;
    skos:prefLabel "german sustainability strategy 2016" ;
    skos:definition "german sustainability strategy 2016 (https://sustainabledevelopment-deutschland.github.io/en/11-1-a)." .

she:Luxembourg a skos:Concept ;
    skos:prefLabel "luxembourg" ;
    skos:definition "un luxembourg durable pour une meilleure qualité de vie (https://environnement.public.lu/dam-assets/documents/developpement-durable/un-luxembourg-plus-durable-pour-une-meilleure-qualite-de-vie-2010.pdf), p. 35." .

she:France a skos:Concept ;
    skos:prefLabel "france" ;
    skos:definition "the law of agricultural and fishery modernization (https://artificialisation.biodiversitetousvivants.fr)." .

she:Switzerland a skos:Concept ;
    skos:prefLabel "switzerland" ;
    skos:definition "schweizerischer bundesrat (2020, p. 22). this target implements sdg target 15.3 and the seventh environment action programme (no net land take). compensation measures included, however, are based on qualitative requirements and measures rather than area related. soil sealing is used as an indicator for land take until a national soil functions map is available." .

@prefix she:  <https://soilwise-he.github.io/soil-health#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

she:FactorsContributingToDifferencesInRiskAssessment a skos:Concept ;
    skos:prefLabel "factors contributing to differences in risk assessment tools and approaches, and to differences in ssvs among eu member states" ;
    skos:narrower she:GeographicalFactors,
                  she:ClimaticFactors,
                  she:CulturalFactors,
                  she:RegulatoryAndPoliticalFactors,
                  she:ScientificFactors .

she:GeographicalFactors a skos:Concept ;
    skos:prefLabel "geographical factors" ;
    skos:narrower she:SoilProperties,
                  she:DepthOfGroundwaterTable .

she:SoilProperties a skos:Concept ;
    skos:prefLabel "soil properties" ;
    skos:definition "(bio)availability affecting ecology as well as filtering function" .

she:DepthOfGroundwaterTable a skos:Concept ;
    skos:prefLabel "depth of groundwater table" ;
    skos:definition "vapour intrusion and, hence, human exposure through inhalation. it also affects the potential impact of soil quality on water quality, since contact time between soil and surface water is shorter in areas with high water tables" .

she:ClimaticFactors a skos:Concept ;
    skos:prefLabel "climatic factors" ;
    skos:narrower she:TimeSpentOutdoors,
                  she:NetAnnualWaterSurplus,
                  she:TemperatureRainfall .

she:TimeSpentOutdoors a skos:Concept ;
    skos:prefLabel "time spent outdoors" ;
    skos:definition "potential contact with soil and, hence, exposure through soil ingestion" .

she:NetAnnualWaterSurplus a skos:Concept ;
    skos:prefLabel "net annual water surplus" ;
    skos:definition "leaching/accumulation is controlled largely by water flux (in combination with soil properties)" .

she:TemperatureRainfall a skos:Concept ;
    skos:prefLabel "temperature/rainfall" ;
    skos:definition "climate controls crop types used by farmers and hence potential uptake of pollutants from soil" .

she:CulturalFactors a skos:Concept ;
    skos:prefLabel "cultural factors" ;
    skos:narrower she:SelfSupplyGardeningSubsistenceFarming,
                  she:UrbanRecreation,
                  she:DrinkingWaterFromPrivateWells .

she:SelfSupplyGardeningSubsistenceFarming a skos:Concept ;
    skos:prefLabel "self-supply gardening, subsistence farming" ;
    skos:definition "exposure through the consumption of vegetables grown in kitchen gardens" .

she:UrbanRecreation a skos:Concept ;
    skos:prefLabel "urban recreation" .

she:DrinkingWaterFromPrivateWells a skos:Concept ;
    skos:prefLabel "drinking water from private wells" ;
    skos:definition "exposure through the consumption of groundwater as drinking water" .

she:RegulatoryAndPoliticalFactors a skos:Concept ;
    skos:prefLabel "regulatory and political factors" ;
    skos:narrower she:PrioritisationOfEconomicAndEnvironmentalValues,
                  she:ComplementaritiesWithOtherExistingLaws,
                  she:Governance .

she:PrioritisationOfEconomicAndEnvironmentalValues a skos:Concept ;
    skos:prefLabel "prioritisation of economic and environmental values" ;
    skos:definition "role and use of background values" .

she:ComplementaritiesWithOtherExistingLaws a skos:Concept ;
    skos:prefLabel "complementarities with other existing laws" ;
    skos:definition "definition of attributes in risk assessment" .

she:Governance a skos:Concept ;
    skos:prefLabel "governance" ;
    skos:definition "authorities involved and responsible; land reclamation policies, spatial planning, drinking water protection" .

she:ScientificFactors a skos:Concept ;
    skos:prefLabel "scientific factors" ;
    skos:narrower she:ScientificAndAnalyticalExperienceAndCooperation,
                  she:FundingRegime .

